// Owner: A1. Reads the generated operation registry (server/src/contracts/operations.ts)
// as text, so plain Node scripts can use it without TypeScript tooling. The file is
// generated by scripts/codegen.sh in a fixed format; if that format changes, this fails
// loudly rather than guessing.
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const SERVER = join(ROOT, 'server');

/** [{ id, method, path, auth, body: 'json' | 'multipart' | 'none', owner, statuses: number[] }] */
export function readOperations() {
  const source = readFileSync(join(SERVER, 'src/contracts/operations.ts'), 'utf8');
  const start = source.indexOf('export const operations = {');
  if (start === -1) throw new Error('operations.ts has no `export const operations = {`');
  const owners = Object.fromEntries(
    [...source.matchAll(/^ {2}([A-Za-z0-9]+): \{ owner: '([A-Z][0-9])'/gm)].map(([, id, o]) => [
      id,
      o,
    ]),
  );
  const ops = [];
  let op;
  let inResponses = false;
  for (const line of source.slice(start).split('\n')) {
    let m;
    if (line.startsWith('} as const')) break;
    if ((m = /^ {2}([A-Za-z0-9]+): \{$/.exec(line))) {
      op = { id: m[1], body: 'none', owner: owners[m[1]] ?? 'A1', statuses: [] };
      inResponses = false;
      ops.push(op);
    } else if (op && /^ {4}responses: \{$/.test(line)) inResponses = true;
    else if (op && inResponses && (m = /^ {6}(\d{3}): /.exec(line))) op.statuses.push(Number(m[1]));
    else if (op && inResponses && /^ {4}\},?$/.test(line)) inResponses = false;
    else if (op && (m = /^ {4}method: '([A-Z]+)',$/.exec(line))) op.method = m[1];
    else if (op && (m = /^ {4}path: '([^']+)',$/.exec(line))) op.path = m[1];
    else if (op && (m = /^ {4}auth: '([a-z]+)',$/.exec(line))) op.auth = m[1];
    else if (op && (m = /^ {4}body: (.+)$/.exec(line))) {
      op.body = m[1].startsWith("'multipart'") ? 'multipart' : 'json';
    }
  }
  const broken = ops.filter((o) => !o.method || !o.path || !o.auth);
  if (ops.length === 0 || broken.length > 0) {
    throw new Error(
      `Could not read operations.ts (${broken.map((o) => o.id).join(', ') || 'none found'})`,
    );
  }
  return ops;
}

/** `/api/matches/{id}/glow` becomes `server/app/api/matches/[id]/glow/route.ts`. */
export function routeFile(path) {
  const segments = path
    .split('/')
    .filter(Boolean)
    .map((s) => s.replace(/^\{(.+)\}$/, '[$1]'));
  return join(SERVER, 'app', ...segments, 'route.ts');
}
